#include "gameplay/ConsumableCatalogue.hpp"
#include <algorithm>
#include <cmath>
namespace elysium::gameplay {bool ConsumableCatalogue::add(ConsumableDef d){if(!d.id||!d.recipe||defs_.contains(d.id))return false;if(!std::isfinite(d.amount)||d.amount<0)d.amount=0;if(!std::isfinite(d.durationSeconds)||d.durationSeconds<0)d.durationSeconds=0;defs_[d.id]=d;return true;}const ConsumableDef*ConsumableCatalogue::find(ContentId id)const{auto i=defs_.find(id);return i==defs_.end()?nullptr:&i->second;}UseResult ConsumableCatalogue::use(const UseRequest&r,const Eligibility&eligible){auto*d=find(r.item);if(!d)return{false,0,r.current,"unknown_consumable",Effect::Food,r.target};if(!r.transactionId||transactions_.contains(r.transactionId))return{false,0,r.current,"duplicate_or_invalid_transaction",d->effect,r.target};if((d->effect==Effect::Repair||d->effect==Effect::SealPatch)&&(!eligible||!eligible(r.target,d->effect,d->compatibleFamilyMask)))return{false,0,r.current,"ineligible_target",d->effect,r.target};double max=std::isfinite(r.maximum)&&r.maximum>0?r.maximum:0;double cur=std::isfinite(r.current)?std::clamp(r.current,0.0,max):0;double applied=d->amount;if(d->effect==Effect::Oxygen||d->effect==Effect::Shield||d->effect==Effect::Fuel||d->effect==Effect::Medical||d->effect==Effect::Food){applied=std::min(applied,max-cur);}transactions_.insert(r.transactionId);return{true,applied,std::clamp(cur+applied,0.0,max>0?max:cur+applied),"",d->effect,r.target};}}
